{"command": "python3 << 'EOF'
import json
with open('/workdir/data/books.json') as f:
    data = json.load(f)
books = data['books']

# Check era distribution per author
author_eras = {}  # author -> set of eras present
author_counts = {}  # author -> {classic_count, modern_count, contemporary_count}

for b in books:
    author = b['author']
    year = b['year']
    if 1800 <= year <= 1949:
        era = 'classic'
    elif 1950 <= year <= 1999:
        era = 'modern'
    elif 2000 <= year <= 2025:
        era = 'contemporary'
    else:
        era = None

    if era:
        if author not in author_counts:
            author_counts[author] = {'classic': 0, 'modern': 0, 'contemporary': 0}
        author_counts[author][era] += 1
        if author not in author_eras:
            author_eras[author] = set()
        author_eras[author].add(era)

# Find authors with total >= 4 and eras_present >= 2
qualifying = []
for author, counts in author_counts.items():
    total = counts['classic'] + counts['modern'] + counts['contemporary']
    eras_present = sum(1 for v in counts.values() if v > 0)
    if total >= 4 and eras_present >= 2:
        qualifying.append(author)
        print(f"Author: {author}, Total: {total}, Eras: {eras_present}, Counts: {counts}")
EOF"}
